	e.MustDo(http.StatusOK, "GET", "/v1/me", e.Acme.Key, nil, &me)
	if me.User.ID != e.Acme.Owner.ID || me.Org.ID != e.Acme.ID || me.Role != "owner" {
		t.Fatalf("me = %+v", me)
	}
	if k, _ := e.Store.APIKeyByToken(e.Acme.Key); k.LastUsedAt == nil {
