)

// Options configure a Server.
type Options struct {
	Clock         clock.Clock            // nil: clock.Real
	Payments      *payments.Service      // required
	Subscriptions *subscriptions.Service // required
	Webhooks      *webhooks.Service      // nil: a service with the default HTTP client and resolver
	Mail          mail.Sender            // nil: an Outbox (nothing is sent)
	Logger        *slog.Logger           // nil: discard
	// BaseURL is the dashboard's address, for links in emails (default "https://app.tally.example").
	BaseURL string
}

// Server serves the API.
type Server struct {
	store   *store.Store
	clock   clock.Clock
	pay     *payments.Service
	subs    *subscriptions.Service
	hooks   *webhooks.Service
	mail    mail.Sender
	log     *slog.Logger
	baseURL string
	mux     *http.ServeMux
	handler http.Handler
}

// New returns a server over a store.
func New(st *store.Store, opt Options) *Server {
	if opt.Payments == nil || opt.Subscriptions == nil {
		panic("api.New: Options.Payments and Options.Subscriptions are required")
	}
	s := &Server{store: st, clock: opt.Clock, pay: opt.Payments, subs: opt.Subscriptions, hooks: opt.Webhooks, mail: opt.Mail, log: opt.Logger,
		baseURL: strings.TrimRight(opt.BaseURL, "/"), mux: http.NewServeMux()}
	if s.clock == nil {
		s.clock = clock.Real{}
	}
	if s.hooks == nil {
		s.hooks = webhooks.New(webhooks.Options{Store: st, Clock: s.clock})
	}
	if s.mail == nil {
		s.mail = &mail.Outbox{}
	}
	if s.log == nil {
		s.log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	if s.baseURL == "" {
		s.baseURL = "https://app.tally.example"
	}
	s.routes()
	s.handler = s.withRequestID(s.recoverPanics(s.mux))
	return s
}

// ServeHTTP implements http.Handler.
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) { s.handler.ServeHTTP(w, r) }

// JSON decodes the body into v, failing the test when it cannot.
func (r *Response) JSON(t testing.TB, v any) {
	t.Helper()
	if err := json.Unmarshal(r.Body, v); err != nil {
		t.Fatalf("response %d is not the JSON expected: %v\n%s", r.Code, err, r.Body)
	}
}

// Map decodes the body as a JSON object.
func (r *Response) Map(t testing.TB) map[string]any {
	t.Helper()
	var m map[string]any
	r.JSON(t, &m)
	return m
}

// String is the status and body, for failure messages.
func (r *Response) String() string { return fmt.Sprintf("%d %s", r.Code, bytes.TrimSpace(r.Body)) }

// Do sends a request to the server with key as its API key ("" for none). A body that is a string or []byte is sent as it
// is; any other non-nil body is sent as JSON.
func (e *Env) Do(method, path, key string, body any) *Response {
	e.T.Helper()
	return e.DoWith(method, path, key, body, nil)
}

// DoWith is Do with extra request headers.
func (e *Env) DoWith(method, path, key string, body any, header http.Header) *Response {
	e.T.Helper()
	var rd io.Reader
	switch b := body.(type) {
	case nil:
	case string:
		rd = strings.NewReader(b)
	case []byte:
		rd = bytes.NewReader(b)
	default:
		raw, err := json.Marshal(b)
		if err != nil {
			e.T.Fatal(err)
		}
		rd = bytes.NewReader(raw)
	}
	req := httptest.NewRequest(method, path, rd)
	if key != "" {
		req.Header.Set("Authorization", "Bearer "+key)
	}
	for k, vs := range header {
		for _, v := range vs {
			req.Header.Add(k, v)
		}
	}
	rec := httptest.NewRecorder()
	e.Server.ServeHTTP(rec, req)
	return &Response{Code: rec.Code, Header: rec.Header(), Body: rec.Body.Bytes()}
}

// MustDo is Do that fails the test unless the answer has the status want, and decodes the body into out (when not nil).
func (e *Env) MustDo(want int, method, path, key string, body, out any) *Response {
	e.T.Helper()
	r := e.Do(method, path, key, body)
	if r.Code != want {
		e.T.Fatalf("%s %s: want %d, got %s", method, path, want, r)
	}
	if out != nil {
		r.JSON(e.T, out)
	}
	return r
}

