// seatsOf is the organization's seats as GET /v1/org shows them.
func seatsOf(t *testing.T, e *apitest.Env, key string) store.Seats {
	t.Helper()
	var o struct {
		Seats store.Seats `json:"seats"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/org", key, nil, &o)
	return o.Seats
}

// checkSeats fails unless the organization uses used seats of a limit.
func checkSeats(t *testing.T, e *apitest.Env, key string, used, limit int) {
	t.Helper()
	if s := seatsOf(t, e, key); s.Used != used || s.Limit == nil || *s.Limit != limit {
		t.Fatalf("seats = %+v, want used %d of %d", s, used, limit)
	}
}

// wantBody fails unless the answer has the status and exactly the JSON body want.
func wantBody(t *testing.T, r *apitest.Response, status int, want map[string]any) {
	t.Helper()
	if r.Code != status || !reflect.DeepEqual(r.Map(t), want) {
		t.Fatalf("want %d %v, got %s", status, want, r)
	}
}

// inviteAs invites email with role and returns the invite.
func inviteAs(t *testing.T, e *apitest.Env, key, email, role string) store.Invite {
	t.Helper()
	var inv store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", key, map[string]string{"email": email, "role": role}, &inv)
	return inv
}

// acceptInvite accepts the invite that was emailed to address, as its new member.
func acceptInvite(t *testing.T, e *apitest.Env, address string) {
	t.Helper()
	for _, m := range e.Mail.Messages() {
		g := regexp.MustCompile(`token=([^\s]+)`).FindStringSubmatch(m.Body)
		if m.To == address && g != nil {
			token, _ := url.QueryUnescape(g[1])
			e.MustDo(http.StatusCreated, "POST", "/v1/invites/accept", "", map[string]string{"token": token, "name": address}, nil)
			return
		}
	}
	t.Fatalf("no invite emailed to %s", address)
}

func TestSeatLimits(t *testing.T) {
	e := apitest.New(t)
	acme := e.Acme.Key
	// Acme is on the team plan (10 seats), and its owner uses one.
	checkSeats(t, e, acme, 1, 10)
	if s := seatsOf(t, e, e.Globex.Key); s.Limit != nil {
		t.Fatalf("business plan seats = %+v, want no limit", s)
	}
	inviteAs(t, e, acme, "a@acme.example", "member")
	inviteAs(t, e, acme, "b@acme.example", "member")
	c := inviteAs(t, e, acme, "c@acme.example", "member")
	inviteAs(t, e, acme, "v@acme.example", "viewer")
	checkSeats(t, e, acme, 4, 10)

	// Four seats are in use, one more than the free plan has, so the downgrade is refused and nothing changes.
	wantBody(t, e.Do("PATCH", "/v1/org", acme, map[string]string{"plan": "free"}), http.StatusConflict,
		map[string]any{"error": "over_seat_limit", "limit": 3.0, "used": 4.0})
	if o, _ := e.Store.Org(e.Acme.ID); o.Plan != store.OrgTeam {
		t.Fatalf("plan = %s after a refused downgrade", o.Plan)
	}

	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+c.ID, acme, nil, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/org", acme, map[string]string{"plan": "free"}, nil)
	checkSeats(t, e, acme, 3, 3)

	// At the free plan's limit, a new invite for a seat is refused, and a viewer's invite is not.
	wantBody(t, e.Do("POST", "/v1/invites", acme, map[string]string{"email": "d@acme.example", "role": "member"}), http.StatusPaymentRequired,
		map[string]any{"error": "seat_limit_reached", "limit": 3.0, "used": 3.0})
	w := inviteAs(t, e, acme, "w@acme.example", "viewer")
	checkSeats(t, e, acme, 3, 3)

	// Revoking an invite frees its seat. Then accepting the invites that hold seats works even at the limit.
	a := inviteAs(t, e, acme, "x@acme.example", "member")
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+a.ID, acme, nil, nil)
	inviteAs(t, e, acme, "d@acme.example", "member")
	checkSeats(t, e, acme, 3, 3)
	for _, address := range []string{"a@acme.example", "v@acme.example", "d@acme.example", "w@acme.example"} {
		if address == "a@acme.example" {
			continue
		}
		acceptInvite(t, e, address)
	}
	checkSeats(t, e, acme, 3, 3)

	// Members now: the owner, d (member), v and w (viewers). A viewer who becomes a member needs a free seat.
	v, _ := e.Store.UserByEmail("v@acme.example")
	wUser, _ := e.Store.UserByEmail("w@acme.example")
	d, _ := e.Store.UserByEmail("d@acme.example")
	wantBody(t, e.Do("PATCH", "/v1/members/"+v.ID, acme, map[string]string{"role": "member"}), http.StatusPaymentRequired,
		map[string]any{"error": "seat_limit_reached", "limit": 3.0, "used": 3.0})
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+wUser.ID, acme, map[string]string{"role": "viewer"}, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+d.ID, acme, map[string]string{"role": "viewer"}, nil)
	checkSeats(t, e, acme, 1, 3)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+v.ID, acme, map[string]string{"role": "member"}, nil)
	checkSeats(t, e, acme, 2, 3)
	_ = w
}

func TestSeatLimitHoldsUnderConcurrentInvites(t *testing.T) {
	e := apitest.New(t)
	// Fill nine of the team plan's ten seats: the owner and eight pending invites. One seat is left.
	for i := range 8 {
		inviteAs(t, e, e.Acme.Key, fmt.Sprintf("p%d@acme.example", i), "member")
	}
	checkSeats(t, e, e.Acme.Key, 9, 10)

	codes := make(chan int, 5)
	var wg sync.WaitGroup
	for i := range 5 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			codes <- e.Do("POST", "/v1/invites", e.Acme.Key, map[string]string{"email": fmt.Sprintf("r%d@acme.example", i), "role": "member"}).Code
		}()
	}
	wg.Wait()
	close(codes)
	created := 0
	for code := range codes {
		switch code {
		case http.StatusCreated:
			created++
		case http.StatusPaymentRequired:
		default:
			t.Fatalf("unexpected status %d", code)
		}
	}
	if created != 1 {
		t.Fatalf("%d of 5 concurrent invites succeeded with one seat left, want 1", created)
	}
	checkSeats(t, e, e.Acme.Key, 10, 10)
}
